const data=window.OVA_CONTENT;document.title=`Sección ${data.number} — ${data.title}`;document.querySelector('#section-title').textContent=data.title;document.querySelector('#section-objective').textContent=data.objective;document.querySelector('#section-number').textContent=`Sección ${data.number} · ${data.minutes} minutos`;document.querySelector('#references-list').innerHTML=data.references.map(x=>`<li>${x}</li>`).join('');const iconFor=i=>['icon-informacion.png','icon-recursos.png','icon-actividades.png','icon-interaccion.png'][i%4];const screens=document.querySelector('#screens');const nav=document.querySelector('#stage-nav');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function activityHtml(a,i){if(a.type==='choice'||a.type==='multi'){const type=a.type==='choice'?'radio':'checkbox';return `<fieldset><legend>${esc(a.question)}</legend>${a.options.map((o,j)=>`<label class="option"><input type="${type}" name="q-${i}" value="${j}"><span>${esc(o)}</span></label>`).join('')}</fieldset>`}if(a.type==='order'){const opts=a.items.map((o,j)=>`<option value="${j}">${esc(o)}</option>`).join('');return `<fieldset><legend>${esc(a.question)}</legend><div class="order-grid">${a.items.map((_,j)=>`<label><span>Posición ${j+1}</span><select><option value="">Seleccionar…</option>${opts}</select></label>`).join('')}</div></fieldset>`}const opts=a.pairs.map(p=>`<option value="${esc(p.value)}">${esc(p.option)}</option>`).join('');return `<fieldset><legend>${esc(a.question)}</legend><div class="relation-grid">${a.pairs.map(p=>`<label><span>${esc(p.label)}</span><select><option value="">Seleccionar…</option>${opts}</select></label>`).join('')}</div></fieldset>`}data.stages.forEach((s,i)=>{nav.insertAdjacentHTML('beforeend',`<button class="stage-button" type="button" data-go="${i}">${i+1}. ${esc(s.eyebrow)}</button>`);screens.insertAdjacentHTML('beforeend',`<section class="screen" data-step="${i}" ${i?'hidden':''}><header class="stage-header"><img class="stage-icon" src="assets/brand/${iconFor(i)}" alt=""><div><p class="eyebrow">${esc(s.eyebrow)}</p><h2>${esc(s.title)}</h2></div></header><details class="reading" open><summary>Lectura de contexto</summary><p>${esc(s.reading)}</p><p class="connection"><strong>Conexión agroindustrial:</strong> ${esc(s.application)}</p></details><form class="activity" data-index="${i}">${activityHtml(s.activity,i)}<button class="button" type="submit">Validar actividad</button><p class="feedback" aria-live="polite"></p></form></section>`)});const stageButtons=[...document.querySelectorAll('.stage-button')],screenList=[...document.querySelectorAll('.screen')],total=screenList.length,key=document.body.dataset.sectionId+'-completed';let current=0,completed=new Set();try{completed=new Set(JSON.parse(localStorage.getItem(key)||'[]').filter(n=>Number.isInteger(n)&&n>=0&&n<total))}catch{}function full(){return completed.size===total&&screenList.every((_,i)=>completed.has(i))}function update(){const pct=Math.round(completed.size/total*100);document.querySelector('#progress-label').textContent=`Avance validado: ${pct} % · ${completed.size} de ${total} actividades`;document.querySelector('#progress-fill').style.width=pct+'%';document.querySelector('.progress-track').setAttribute('aria-valuenow',pct);stageButtons.forEach((b,i)=>b.classList.toggle('is-complete',completed.has(i)));document.querySelector('#completion').hidden=!full()}function show(i,focus=true){current=(i+total)%total;screenList.forEach((s,j)=>s.hidden=j!==current);stageButtons.forEach((b,j)=>{b.classList.toggle('is-current',j===current);b.setAttribute('aria-current',j===current?'step':'false')});document.querySelector('#position').textContent=`Actividad ${current+1} de ${total}`;if(focus)screenList[current].scrollIntoView({behavior:'smooth',block:'start'})}function actual(form,type){if(type==='choice'||type==='multi')return[...form.querySelectorAll('input:checked')].map(x=>Number(x.value)).sort((a,b)=>a-b);return[...form.querySelectorAll('select')].map(x=>type==='order'?(x.value===''?'':Number(x.value)):x.value)}stageButtons.forEach(b=>b.onclick=()=>show(Number(b.dataset.go)));document.querySelector('#previous').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelectorAll('.activity').forEach((form,i)=>form.onsubmit=e=>{e.preventDefault();const a=data.stages[i].activity,got=actual(form,a.type),feedback=form.querySelector('.feedback');if(!got.length||got.some(v=>v===''||Number.isNaN(v))){feedback.textContent='Completa todos los campos antes de validar.';feedback.className='feedback error';return}if(JSON.stringify(got)===JSON.stringify(a.answer)){completed.add(i);localStorage.setItem(key,JSON.stringify([...completed]));feedback.textContent='Correcto. '+a.success;feedback.className='feedback success';update()}else{feedback.textContent='Aún no. Revisa la lectura, ajusta tu respuesta e inténtalo nuevamente.';feedback.className='feedback error'}});document.querySelector('#restart').onclick=()=>{if(!confirm('¿Deseas borrar el avance y reiniciar esta sección?'))return;completed.clear();localStorage.removeItem(key);document.querySelectorAll('.activity').forEach(f=>{f.reset();f.querySelector('.feedback').textContent=''});update();show(0)};document.querySelector('#download-badge').onclick=()=>{if(!full())return;const name=esc(document.querySelector('#student-name').value.trim()||'Estudiante'),title=esc(data.title);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200"><rect width="1200" height="1200" rx="70" fill="#f7faf5"/><rect width="1200" height="250" fill="#1f5d45"/><circle cx="600" cy="500" r="245" fill="#d4af37" stroke="#8f6810" stroke-width="32"/><g opacity=".45" fill="none" stroke="#5d4105" stroke-width="14"><path d="M585 315c-70-45-135 8-120 75-70 28-70 115-12 145-18 75 65 125 120 75 45 60 145 25 140-55 70-25 70-120 5-145 10-70-75-110-125-60-5-15-5-20-8-35Z"/><path d="M590 315v300M470 390h80v60h40M450 500h100v55h40M710 390h-80v60h-40M750 500h-100v55h-60"/></g><text x="600" y="455" text-anchor="middle" font-family="Arial" font-weight="800" font-size="55">INSIGNIA</text><text x="600" y="580" text-anchor="middle" font-family="Arial" font-weight="900" font-size="120">100%</text><text x="600" y="650" text-anchor="middle" font-family="Arial" font-weight="800" font-size="30">CUMPLIMIENTO VALIDADO</text><text x="600" y="835" text-anchor="middle" font-family="Arial" font-weight="800" font-size="38">${title}</text><text x="600" y="925" text-anchor="middle" font-family="Arial" font-size="38">Otorgada a ${name}</text><text x="600" y="1000" text-anchor="middle" font-family="Arial" font-size="27">Universidad de Cartagena · Biología Aplicada</text></svg>`;const blob=new Blob([svg],{type:'image/svg+xml'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=document.body.dataset.sectionId+'-insignia.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};document.querySelector('.catalog-link').onclick=e=>{if(window.parent===window)return;e.preventDefault();window.parent.postMessage({type:'ova-back-catalog'},'*')};update();show(0,false);